(function() {
    'use strict';

    tinymce.PluginManager.add('small', function(editor) {

        // Enregistre le format 'small'
        editor.settings.formats = editor.settings.formats || {};
        editor.settings.formats.small = {
            inline: 'small',
            remove: 'all'
        };

        editor.addButton('small', {
            icon: false,
            image: 'data:image/svg+xml;base64,CjxzdmcgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIiB3aWR0aD0iMjAwIiBoZWlnaHQ9IjIwMCIgdmlld0JveD0iMCAwIDMyIDMyIj48cGF0aCBmaWxsPSIjNTA1NzVlIiBkPSJNMjMgMjdWMTVoLTV2LTJoMTJ2MmgtNXYxMmgtMnoiLz48cGF0aCBmaWxsPSIjNTA1NzVlIiBkPSJNMTEgMjdWOEgyVjZoMjB2MmgtOXYxOWgtMnoiLz48L3N2Zz4=',
            tooltip: 'Small',
            onclick: function() {
                editor.formatter.toggle('small');
            },
            onPostRender: function() {
                var btn = this;
                editor.on('NodeChange', function(e) {
                    btn.active(editor.formatter.match('small'));
                });
            }
        });

    });

})();